const pptxgen = require('pptxgenjs');
const fs = require('fs');
const path = require('path');

const pptx = new pptxgen();
pptx.layout = 'LAYOUT_16X9';
pptx.author = 'OpenAI';
pptx.company = 'OpenAI';
pptx.subject = "Ethereum post-merge supply dynamics and monetary premium";
pptx.title = "Ultra Sound Money: Ethereum's Post-Merge Supply Dynamics and Monetary Premium";
pptx.lang = 'en-US';
pptx.theme = {
  headFontFace: 'Arial',
  bodyFontFace: 'Arial',
  lang: 'en-US'
};
pptx.defineLayout({ name: 'CUSTOM_LAYOUT', width: 10, height: 5.625 });
pptx.layout = 'CUSTOM_LAYOUT';
pptx.margin = 0;
pptx.chartColors = ['627EEA', '8A92B2', 'D4AF37', 'FF6B6B', '15C784', 'A78BFA'];
pptx.layout = 'CUSTOM_LAYOUT';
pptx._slides = pptx._slides || [];

const C = {
  bg: '070A12',
  bg2: '0B1020',
  panel: '111827',
  panel2: '172033',
  panel3: '0E1726',
  text: 'F8FAFC',
  muted: '94A3B8',
  dim: '64748B',
  eth: '627EEA',
  blue: '38BDF8',
  gold: 'D4AF37',
  green: '15C784',
  red: 'EF4444',
  orange: 'F59E0B',
  purple: 'A78BFA',
  line: '243044',
  white: 'FFFFFF',
};

const W = 10;
const H = 5.625;
const outFile = '/app/output/final_deck.pptx';
const assets = '/app/benchmark/assets';

function addBg(slide, variant = 'base') {
  slide.background = { color: variant === 'deep' ? '030712' : C.bg };
  slide.addShape(pptx.ShapeType.rect, { x: 0, y: 0, w: W, h: H, fill: { color: variant === 'deep' ? '030712' : C.bg }, line: { color: variant === 'deep' ? '030712' : C.bg } });
  slide.addShape(pptx.ShapeType.arc, { x: 6.9, y: -1.2, w: 4.8, h: 4.8, adjustPoint: 0.25, rotate: 25, line: { color: C.eth, transparency: 78, width: 2 }, fill: { color: C.bg, transparency: 100 } });
  slide.addShape(pptx.ShapeType.arc, { x: -1.7, y: 3.9, w: 3.3, h: 3.3, adjustPoint: 0.25, rotate: 215, line: { color: C.gold, transparency: 84, width: 1.4 }, fill: { color: C.bg, transparency: 100 } });
}

function title(slide, text, subtitle) {
  slide.addText(text, { x: 0.38, y: 0.25, w: 7.6, h: 0.38, fontFace: 'Arial', fontSize: 16, bold: true, color: C.text, margin: 0 });
  slide.addShape(pptx.ShapeType.line, { x: 0.38, y: 0.72, w: 9.25, h: 0, line: { color: C.line, width: 1 } });
  if (subtitle) slide.addText(subtitle, { x: 0.4, y: 0.78, w: 8.3, h: 0.28, fontSize: 7.5, color: C.muted, margin: 0 });
}

function page(slide, n) {
  slide.addShape(pptx.ShapeType.roundRect, { x: 9.28, y: 5.07, w: 0.34, h: 0.23, rectRadius: 0.05, fill: { color: C.panel2 }, line: { color: C.line, transparency: 20 } });
  slide.addText(String(n).padStart(2, '0'), { x: 9.28, y: 5.11, w: 0.34, h: 0.12, align: 'center', fontSize: 6, color: C.muted, margin: 0 });
}

function pill(slide, text, x, y, w, color = C.eth, fillTrans = 82) {
  slide.addShape(pptx.ShapeType.roundRect, { x, y, w, h: 0.24, rectRadius: 0.06, fill: { color, transparency: fillTrans }, line: { color, transparency: 20, width: 0.7 } });
  slide.addText(text, { x: x + 0.07, y: y + 0.055, w: w - 0.14, h: 0.11, fontSize: 6.5, bold: true, color: C.text, align: 'center', margin: 0 });
}

function metric(slide, label, value, x, y, w, accent = C.eth, note = '') {
  slide.addShape(pptx.ShapeType.roundRect, { x, y, w, h: 0.95, rectRadius: 0.06, fill: { color: C.panel, transparency: 2 }, line: { color: C.line, width: 0.8 } });
  slide.addShape(pptx.ShapeType.rect, { x, y, w: 0.05, h: 0.95, fill: { color: accent }, line: { color: accent } });
  slide.addText(value, { x: x + 0.14, y: y + 0.18, w: w - 0.22, h: 0.25, fontSize: 18, bold: true, color: C.text, margin: 0, breakLine: false, fit: 'shrink' });
  slide.addText(label, { x: x + 0.14, y: y + 0.53, w: w - 0.22, h: 0.17, fontSize: 7.5, bold: true, color: C.muted, margin: 0 });
  if (note) slide.addText(note, { x: x + 0.14, y: y + 0.72, w: w - 0.22, h: 0.13, fontSize: 5.8, color: C.dim, margin: 0 });
}

function bar(slide, x, y, w, h, value, max, color, label, valueText, opts = {}) {
  slide.addShape(pptx.ShapeType.roundRect, { x, y, w, h, rectRadius: 0.03, fill: { color: C.panel2 }, line: { color: C.panel2 } });
  const bw = Math.max(0.02, (value / max) * w);
  slide.addShape(pptx.ShapeType.roundRect, { x, y, w: bw, h, rectRadius: 0.03, fill: { color }, line: { color } });
  slide.addText(label, { x, y: y - 0.19, w: w * 0.62, h: 0.13, fontSize: opts.fs || 7, color: C.text, bold: opts.bold || false, margin: 0 });
  slide.addText(valueText, { x: x + w * 0.62, y: y - 0.19, w: w * 0.38, h: 0.13, fontSize: opts.fs || 7, color: opts.valueColor || C.muted, bold: true, align: 'right', margin: 0 });
}

function note(slide, text, x, y, w, h, accent = C.gold) {
  slide.addShape(pptx.ShapeType.roundRect, { x, y, w, h, rectRadius: 0.05, fill: { color: C.panel3, transparency: 2 }, line: { color: accent, transparency: 35, width: 0.8 } });
  slide.addShape(pptx.ShapeType.rect, { x, y, w: 0.04, h, fill: { color: accent }, line: { color: accent } });
  slide.addText(text, { x: x + 0.14, y: y + 0.12, w: w - 0.24, h: h - 0.2, fontSize: 8, color: C.text, breakLine: false, fit: 'shrink', valign: 'mid', margin: 0.02 });
}

function addWaterfall(slide) {
  const x0 = 0.72, y0 = 4.55, chartW = 4.2, chartH = 2.45;
