  ];
  bars.forEach(b => {
    slide.addShape(pptx.ShapeType.roundRect, { x: b.x, y: b.y, w: 0.65, h: b.h, rectRadius: 0.03, fill: { color: b.color }, line: { color: b.color } });
    slide.addText(b.val, { x: b.x - 0.25, y: b.y - 0.25, w: 1.15, h: 0.14, fontSize: 7, bold: true, color: C.text, align: 'center', margin: 0 });
    slide.addText(b.label, { x: b.x - 0.25, y: baseY + 0.12, w: 1.15, h: 0.14, fontSize: 6.5, color: C.muted, align: 'center', margin: 0 });
  });
  slide.addShape(pptx.ShapeType.line, { x: x0 + 0.85, y: baseY - issueH, w: 0.9, h: 0, line: { color: C.line, width: 1, dash: 'dash' } });
  slide.addShape(pptx.ShapeType.line, { x: x0 + 2.4, y: baseY - issueH + 0.02, w: 0.9, h: 0.02, line: { color: C.line, width: 1, dash: 'dash' } });
  pill(slide, 'Burn offset ratio: 0.01x', x0 + 1.3, 2.28, 1.75, C.red, 78);
  slide.addText('Burns offset only ~1% of new issuance over the trailing week.', { x: x0 + 0.42, y: 4.88, w: 3.3, h: 0.15, fontSize: 6.4, color: C.dim, align: 'center', margin: 0 });
