function addGauge(slide) {
  const x = 0.78, y = 2.34, w = 4.45;
  slide.addText('7-day base gas range (Gwei)', { x, y: 1.82, w: 3.3, h: 0.16, fontSize: 8, bold: true, color: C.text, margin: 0 });
  slide.addShape(pptx.ShapeType.line, { x, y: y + 0.45, w, h: 0, line: { color: C.line, width: 10, beginArrowType: 'none', endArrowType: 'none' } });
