  slide.addShape(pptx.ShapeType.line, { x: x + w * 0.5, y: y + 1.34, w: 0, h: 0.35, line: { color: C.orange, width: 2, dash: 'dash' } });
  slide.addText('far above current range', { x: x + 1.2, y: y + 1.66, w: 2.1, h: 0.13, fontSize: 6.5, color: C.orange, align: 'center', margin: 0 });
}

function addProjectionChart(slide) {
  const x = 0.6, y = 1.72, w = 5.35, h = 2.55;
  slide.addText('200-year supply trajectory: current → equilibrium', { x, y: 1.34, w, h: 0.16, fontSize: 8.5, bold: true, color: C.text, margin: 0 });
  slide.addShape(pptx.ShapeType.roundRect, { x, y, w, h, rectRadius: 0.06, fill: { color: C.panel, transparency: 4 }, line: { color: C.line, width: 0.8 } });
  const padL = 0.55, padR = 0.22, padT = 0.25, padB = 0.42;
  const px = x + padL, py = y + padT, pw = w - padL - padR, ph = h - padT - padB;
  // Axes use only source figures: 121.6M current supply and 125.7M equilibrium over 200 years.
  const yMin = 121.0, yMax = 126.0;
  const sx = t => px + (t / 200) * pw;
  const sy = v => py + (1 - (v - yMin) / (yMax - yMin)) * ph;
  [121.0, 123.0, 125.7, 126.0].forEach(v => {
    const yy = sy(v);
    slide.addShape(pptx.ShapeType.line, { x: px, y: yy, w: pw, h: 0, line: { color: C.line, transparency: 25, width: 0.5 } });
    slide.addText(v === 125.7 ? '125.7M eq.' : `${v.toFixed(0)}M`, { x: x + 0.08, y: yy - 0.06, w: 0.42, h: 0.12, fontSize: 5.5, color: v === 125.7 ? C.gold : C.dim, margin: 0, align: 'right' });
  });
  [0, 200].forEach(t => {
    slide.addText(t === 0 ? 'Now' : 'Year 200', { x: sx(t) - 0.25, y: y + h - 0.28, w: 0.55, h: 0.12, fontSize: 5.8, color: C.muted, align: 'center', margin: 0 });
  });
  slide.addShape(pptx.ShapeType.line, { x: px, y: sy(125.7), w: pw, h: 0, line: { color: C.gold, transparency: 15, width: 1.2, dash: 'dash' } });
  slide.addShape(pptx.ShapeType.line, { x: sx(0), y: sy(121.60398), w: sx(200) - sx(0), h: sy(125.7) - sy(121.60398), line: { color: C.eth, width: 3, beginArrowType: 'none', endArrowType: 'triangle' } });
  slide.addShape(pptx.ShapeType.oval, { x: sx(0) - 0.05, y: sy(121.60398) - 0.05, w: 0.1, h: 0.1, fill: { color: C.eth }, line: { color: C.eth } });
  slide.addShape(pptx.ShapeType.oval, { x: sx(200) - 0.055, y: sy(125.7) - 0.055, w: 0.11, h: 0.11, fill: { color: C.gold }, line: { color: C.gold } });
  slide.addText('121.6M ETH current', { x: sx(0) + 0.08, y: sy(121.60398) + 0.06, w: 1.1, h: 0.13, fontSize: 6.3, color: C.text, margin: 0 });
  slide.addText('125.7M ETH equilibrium', { x: sx(200) - 1.55, y: sy(125.7) - 0.28, w: 1.55, h: 0.13, fontSize: 6.3, bold: true, color: C.gold, align: 'right', margin: 0 });
  slide.addText('Visual guide from source endpoints; model assumption: 39M staked + 22 Gwei avg base gas.', { x: x + 0.12, y: y + h + 0.08, w: w - 0.24, h: 0.12, fontSize: 5.6, color: C.dim, align: 'center', margin: 0 });
}

function addPie(slide, cx, cy, r, data, total, label) {
  // Approximate pie with stacked horizontal composition bar for precision and readability.
  const x = cx - r, y = cy - 0.18, w = r * 2, h = 0.36;
  let offset = 0;
  data.forEach(d => {
    const dw = w * d.value / total;
    slide.addShape(pptx.ShapeType.rect, { x: x + offset, y, w: dw, h, fill: { color: d.color }, line: { color: d.color } });
    offset += dw;
  });
  slide.addShape(pptx.ShapeType.roundRect, { x, y, w, h, rectRadius: 0.04, fill: { color: 'FFFFFF', transparency: 100 }, line: { color: C.line, width: 0.5 } });
  slide.addText(label, { x, y: y - 0.28, w, h: 0.14, fontSize: 7.5, color: C.text, bold: true, align: 'center', margin: 0 });
}

